SegueShard:
    """Intermediary between shards — handles data, tone, timing, intent."""
    def __init__(self,stype:str,behavior:str,smoothing:str="default",meta:Optional[Dict[str,Any]]=None):
        self.stype=stype; self.behavior=behavior; self.smoothing=smoothing
        self.meta=meta or {}; self.created=utcnow()
    def apply(self,data:Dict[str,Any])->Dict[str,Any]:
        if self.stype=="context" and self.behavior=="carry":
            data["context_carried"]=True
        elif self.stype=="temporal" and self.behavior=="fade":
            data["transition"]="smoothed"
        elif self.stype=="semantic" and self.behavior=="tone_mapper":
            data["voice"]="savant"
        elif self.stype=="transform" and self.behavior=="normalize":
            data={k.lower():v for k,v in data.items()}
        elif self.stype=="aesthetic" and self.behavior=="easing":
            data["curve"]="ease_in_out"
        return data
    def to_dict(self)->Dict[str,Any]:
        return {"type":self.stype,"behavior":self.behavior,
                "smoothing":self.smoothing,"created":self.created}

