SegueRegistry:
    """Registers shard linkages and injects appropriate segue shards."""
    def __init__(self,root:Path):
        self.root=root; self.segues:List[Segue]=[]; self.segue_shards:List[SegueShard]=[]
    def infer(self,src:Shard,tgt:Shard)->SegueShard:
        mapping={
            ("data","data"):("context","carry"),
            ("ui","ui"):("aesthetic","easing"),
            ("text","text"):("semantic","tone_mapper"),
            ("logic","logic"):("transform","normalize"),
            ("data","ui"):("bridge","schema_harmonizer"),
        }
        stype,beh=mapping.get((src.type,tgt.type),("context","carry"))
        return SegueShard(stype,beh,"smooth")
    def link(self,src:Shard,tgt:Shard,mode="chain"):
        seg=Segue(src.id,tgt.id,mode); self.segues.append(seg)
        segue_shard=self.infer(src,tgt); self.segue_shards.append(segue_shard)
        return seg,segue_shard
    def export(self):
        data={"generated":utcnow(),
              "segues":[s.to_dict() for s in self.segues],
              "segue_shards":[s.to_dict() for s in self.segue_shards]}
        out=self.root/"segue_registry.json"
        out.write_text(json.dumps(data,indent=2))
        print(f"✅ Segue registry exported → {out}")

