    def __init__(self):
        self.tasks=[]
        if DATA.exists():
            try:self.load()
            except: self.tasks=[]
    def load(self):
        raw=json.loads(DATA.read_text())
        def build(d,parent=None):
            t=Task(d["title"],d["priority"],parent,d["type"])
            t.id=d["id"];t.status=d["status"]
            t.created=d["created"];t.updated=d["updated"]
            t.children=[build(c,t.id) for c in d.get("children",[])]
            return t
        self.tasks=[build(d) for d in raw]
    def save(self):
        DATA.parent.mkdir(parents=True,exist_ok=True)
        DATA.write_text(json.dumps([t.to_dict() for t in self.tasks],indent=2))
        self.export_download()
    def export_download(self):
        EXPORT.parent.mkdir(parents=True,exist_ok=True)
        summary={"generated":utcnow(),"tasks":[t.to_dict() for t in self.tasks]}
        EXPORT.write_text(json.dumps(summary,indent=2))
        print(f"📤 Exported current lattice → {EXPORT}")

    # ----- creation -----
    def create_from_path(self, path:Path, recursive:bool):
        """Builds a task tree from the given element or project path"""
        if not path.exists():
            print(f"❌ Path not found: {path}"); return
        root_task=Task(path.name,3,None,"project" if path.is_dir() else "element")
        self.tasks=[root_task]
        if path.is_dir() and recursive:
            for dirpath,dirnames,filenames in os.walk(path):
                parent_id=None
                rel=str(Path(dirpath).relative_to(path))
                if rel!=".": parent_id=root_task.id
                for d in dirnames:
                    child=Task(d,3,parent_id,"folder")
                    root_task.children.append(child)
                for f in filenames:
                    child=Task(f,3,parent_id,"file")
                    root_task.children.append(child)
        elif path.is_dir():
            # only top-level
            for item in path.iterdir():
                ttype="folder" if item.is_dir() else "file"
                root_task.children.append(Task(item.name,3,root_task.id,ttype))
        self.save()

    # ----- manual interaction -----
    def add(self,title,priority=3,parent=None):
        t=Task(title,priority,parent); self.tasks.append(t); self.save()
    def mark(self,tid,status):
        def search(lst):
            for t in lst:
                if t.id==tid: return t
                r=search(t.children)
                if r: return r
        t=search(self.tasks)
        if t:
            t.status=status;t.updated=utcnow();self.save()
    def show(self,tasks=None,level=0):
        tasks=tasks or self.tasks
        for t in tasks:
            pad=" "*(level*2)
            print(f"{pad}- [{t.status[:1].upper()}] {t.title} ({t.type}) id:{t.id}")
            self.show(t.children,level+1)

