        raise FileNotFoundError("PROJECT_RULES.md missing")
    data = RULES.read_text().splitlines()
    rules = []
    cur = None
    for line in data:
        if re.match(r"^\d+\.", line.strip()):
            if cur: rules.append(cur)
            num, text = line.split(".",1)
            cur = {"id":num.strip(),"rule":text.strip()}
        elif cur and line.strip():
            cur["rule"] += " "+line.strip()
    if cur: rules.append(cur)
    return rules

