        else: print("❌ No backup available.")
        return
    for f in folder.rglob('*'):
        if f.is_file() and f.stat().st_size == 0:
            print(f"⚠️ Empty file detected: {f}")
            backup=find_backup(folder.name)
            if backup:
                src=list(backup.rglob(f.name))
                if src: shutil.copy(src[0], f); print(f"✅ Repaired {f} from backup.")
    open(LOG,'a').write(f"[{time.strftime('%H:%M:%S')}] verified {folder}\n")

